const body = $('Webhook').first().json.body;

return [{
  json: {

    // Company Information
    company_name: body.company || "",
    industry: body.industry || "FMCG",
    country: body.country || "India",

    // Meeting Information
    meeting_id: body.meeting_id || "",
    meeting_title: body.meeting_title || "",
    meeting_date: body.meeting_date || "",
    meeting_time: body.meeting_time || "",
    meeting_location: body.meeting_location || "",
    meeting_description: body.meeting_description || "",

    // User Information
    user_email: body.user_email || "",

    // Metadata
    source: body.source || "Google Calendar",
    generated_at: new Date().toISOString()
  }
}];

const company = $("Code in JavaScript").first().json.company_name;
const brief = $("AI Agent").first().json.output;

return [
  {
    json: {
      status: "completed",
      company: company,
      brief_html: brief
    }
  }
];
